 "content": "def transform(grid):
    # Swap the two colors, mapping the most frequent/background color to 0.
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda v: sum(row.count(v) for row in grid))
    other = next(v for v in colors if v != bg)
    return [[other if v == bg else bg for v in row] for row in grid]
"
